  communityStrength: number;      // [0,1] Local cohesion, mutual aid
  culturalVitality: number;       // [0,1] Art, creativity, expression

  // Tier 4: Health and Longevity (weight: 0.15)
  healthcareQuality: number;      // [0,1] Medical outcomes, access
