      trainingDataQuality: 0.5, // Neutral training data quality (baseline)
      structuralChoices: {
        regulationType: 'none',
        ubiVariant: 'none',
        surveillanceLevel: 0,
        internationalCoordination: false
      },
      // Phase 4: Cybersecurity arms race
      cyberDefense: {
        securityHardening: 3.0,
