  // Crisis response
  crisisVulnerability: number; // 0-1 (0 = insulated, 1 = highly exposed)
  adaptability: number;        // 0-1 (ability to cope with change)
  survivalRate: number;        // Multiplier on mortality (0.5 = half the death rate, 2.0 = double)

