    phase: 'declining' | 'crisis' | 'collapse';
  };

  // Specific Tipping Points (Realistic Timeline Recalibration)
  specificTippingPoints?: {
    amazon: {
      deforestation: number;
      tippingThreshold: number;
      triggered: boolean;
      triggeredAt: number;
      transitionProgress: number;
      carbonReleased: number;
