          console.log(`  Gains to Capital: ${(state.laborCapitalDistribution.gainsToCapital * 100).toFixed(0)}%`);
          console.log(`  Labor Share: ${(state.laborCapitalDistribution.laborShare * 100).toFixed(1)}%`);
        }
      }
    }

    return { events: [] };
  }
}

