export function calculateUnemploymentFloor(jobGuaranteeLevel: number): number {
  // Job guarantee creates unemployment floor
  // 0 = no floor (20% baseline in crisis)
  // 1.0 = 5% floor (universal program)
  const baseFloor = 0.20;  // 20% unemployment in worst case without program
  const maxReduction = 0.15;  // Can reduce by up to 15 percentage points
  return Math.max(0.05, baseFloor - (jobGuaranteeLevel * maxReduction));
}

