    23→/**
    24→ * Calculate environmental mortality rate based on threshold crossings
    25→ *
    26→ * Research-based (UNEP 2024, PNAS 2014):
    27→ * - Current (2025): 7/9 boundaries, 9M deaths/8B people = 0.009% monthly
    28→ * - Mortality scales with food, water, climate, biodiversity thresholds
    29→ * - Non-linear escalation when multiple systems fail
    30→ *
    31→ * FIX (Oct 13, 2025): Now returns breakdown by cause to properly track deaths
    32→ * P0.6 (Oct 15, 2025): Episodic environmental shocks instead of continuous noise
    33→ * Research: Real environmental disasters are episodic (heatwaves, droughts, famines)
    34→ *   - Events occur with ~5% monthly probability based on environmental stress
    35→ *   - Events cause 50-200% mortality spikes for 3-12 months
    36→ *   - Between events: minimal variation (baseline + small noise)
    37→ * Returns monthly mortality rate (0-1, where 0.01 = 1% die per month)
    38→ */
    39→export function calculateEnvironmentalMortality(state: GameState, month: number): EnvironmentalMortalityBreakdown {
    40→  const env = state.environmentalAccumulation;
    41→  const boundaries = state.planetaryBoundariesSystem;
    42→  if (!env || !boundaries) {
    43→    return { total: 0, famine: 0, disease: 0, climate: 0, ecosystem: 0, pollution: 0 };
    44→  }
    45→  
    46→  let famineMortality = 0;
    47→  let diseaseMortality = 0;
    48→  let climateMortality = 0;
    49→  let ecosystemMortality = 0;
    50→  let pollutionMortality = 0;
    51→  
    52→  // === BASELINE (Current 2025 conditions) ===
    53→  // 7/9 boundaries breached = 0.009% monthly (UNEP: 9M deaths/year globally)
    54→  // Pollution is the main driver of current baseline mortality
    55→  if (boundaries.boundariesBreached >= 7) {
    56→    pollutionMortality = 0.00009; // 0.009% baseline
    57→  }
    58→  
    59→  // === FOOD SECURITY (Highest immediate impact) ===
    60→  // Food < 0.4 = crisis, Food < 0.2 = catastrophic
    61→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, not environmentalAccumulation
    62→  const foodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
    63→  if (foodSecurity < 0.4) {
    64→    const foodSeverity = (0.4 - foodSecurity) / 0.4; // 0-1 scale
    65→    famineMortality += 0.0001 * Math.pow(foodSeverity, 1.5); // 0.01%/month at threshold, scales up
    66→    
    67→    if (foodSecurity < 0.2) {
    68→      // Catastrophic food crisis: additional mortality
