    76→  const waterSecurity = env.waterSecurity || 0.7;
    77→  if (waterSecurity < 0.4) {
    78→    const waterSeverity = (0.4 - waterSecurity) / 0.4;
    79→    diseaseMortality += 0.00008 * Math.pow(waterSeverity, 1.5); // Slightly less immediate than food
    80→  }
    81→  
    82→  // === CLIMATE STABILITY (Heat stress, disasters) ===
    83→  // Climate < 0.5 = severe, Climate < 0.3 = catastrophic
    84→  const climateStability = env.climateStability || 0.75;
