    87→    climateMortality += 0.00005 * Math.pow(climateSeverity, 2); // Non-linear escalation
    88→  }
    89→  
    90→  // === BIODIVERSITY LOSS (Ecosystem services collapse) ===
    91→  // Biodiversity < 0.3 = critical, < 0.2 = collapse
    92→  // Loss of pollination, disease regulation, etc.
