    96→    ecosystemMortality += 0.00003 * Math.pow(bioSeverity, 1.5); // Pollination, disease regulation lost
    97→  }
    98→  
    99→  // === CASCADE AMPLIFICATION (Non-Linear Feedback) ===
   100→  // When multiple systems fail simultaneously, effects compound
   101→  const breachedCount = boundaries.boundariesBreached;
   102→  if (breachedCount >= 8) {
   103→    const cascadeAmplifier = 1.0 + Math.pow((breachedCount - 7) / 2, 2); // 1.0x → 2.25x at 9/9
   104→    famineMortality *= cascadeAmplifier;
