   324→    // NEW: Distribution Metrics (Oct 12, 2025)
   325→    // Baseline 2025: Moderate inequality, some regional crises
   326→    distribution: {
   327→      globalGini: 0.38,              // Current global Gini ~0.38 (World Bank)
   328→      regionalVariance: 0.08,        // Moderate variance
