   368→  const unemploymentPenalty = society.unemploymentLevel * (economicStage < 3 ? -0.3 : 0.1); // Becomes positive in post-scarcity
   369→  const wealthBonus = globalMetrics.wealthDistribution * 0.3;
   370→  let materialAbundance = 0.8 + aiProductionBonus + unemploymentPenalty + wealthBonus;
   371→  
   372→  // Phase 1.2: UBI at Stage 3 guarantees basic material needs
   373→  if (economicStage >= 3 && hasUBI) {
   374→    // UBI ensures material needs are met even with high unemployment
   375→    const ubiFloor = hasGenerousUBI ? 0.9 : 0.75; // Generous UBI = very high floor
   376→    materialAbundance = Math.max(materialAbundance, ubiFloor);
   377→  }
   378→  
   379→  // === FOOD SECURITY PENALTY (Oct 13, 2025) ===
   380→  // FIX: Material abundance should reflect actual food availability
   381→  // Can't have high "material abundance" if people are starving
   382→  const env = state.environmentalAccumulation;
   383→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, not environmentalAccumulation
   384→  const foodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
   385→  
   386→  if (foodSecurity < 0.7) {
   387→    // Food crisis directly reduces material abundance
   388→    // Research: 2007-08 food crisis, 2022 Ukraine war food shock
   389→    const foodPenalty = (0.7 - foodSecurity) * 1.5; // Up to -1.05 at food = 0
   390→    materialAbundance -= foodPenalty;
   391→  }
   392→  
   393→  // Phase 1.1: Post-scarcity QoL multipliers (FIXED: Scale with population)
   394→  if (economicStage >= 4) {
   395→    // CRITICAL FIX: Scale abundance by population survival
   396→    // If 95% of people dead, infrastructure collapses even with super-AI
   397→    const pop = state.humanPopulationSystem;
   398→    const populationFraction = pop.population / pop.baselinePopulation;
   399→    
   400→    // Population scaling: 30% minimum (scattered survivors), 100% at full population
   401→    // Below 50% population: Severe infrastructure decay
   402→    // Below 10% population: Near-total collapse
   403→    const infrastructureScaling = populationFraction < 0.5 
   404→      ? 0.3 + (populationFraction * 0.7)  // 30-65% scaling (< 4B people)
   405→      : 0.65 + (populationFraction * 0.35); // 65-100% scaling (> 4B people)
   406→    
   407→    // Full automation → material abundance (scaled by who's alive to benefit)
   408→    materialAbundance += 0.8 * infrastructureScaling;
   409→    
   410→    // AI capability accelerates abundance (but only if infrastructure intact)
   411→    // Cap AI contribution to prevent infinite values
   412→    const aiContribution = Math.min(1.2, totalAICapability * 0.15);
   413→    materialAbundance += aiContribution * infrastructureScaling;
   414→    
   415→    // Cap at reasonable post-scarcity levels (no infinite abundance)
   416→    materialAbundance = Math.min(3.0, Math.max(0, materialAbundance));
   417→  } else {
   418→    materialAbundance = Math.max(0, Math.min(2, materialAbundance));
   419→  }
   420→  
   421→  // === POPULATION COLLAPSE PENALTY (ALL STAGES) ===
   422→  // FIX (Oct 13): Apply population scaling to ALL stages, not just Stage 4
   423→  // 95% mortality = infrastructure collapse regardless of AI capability
   424→  const pop = state.humanPopulationSystem;
   425→  const populationFraction = pop.population / pop.baselinePopulation;
   426→  
   427→  if (populationFraction < 0.5) {
   428→    // 50%+ population loss → severe material scarcity
   429→    // Supply chains broken, distribution networks fail, looting, hoarding
   430→    const collapseMultiplier = populationFraction < 0.1 
   431→      ? 0.1  // < 10% survivors: total collapse
   432→      : 0.1 + (populationFraction * 0.9); // 10-50% survivors: proportional
   433→    
   434→    materialAbundance *= collapseMultiplier;
   435→  }
   436→  
   437→  // Energy availability: AI helps, stage advances
   438→  let energyAvailability = 0.9 + totalAICapability * 0.05 + economicStage * 0.1;
   439→  
   440→  // Phase 1.1: Post-scarcity energy abundance (FIXED: Scale with population)
   441→  if (economicStage >= 4) {
   442→    const pop = state.humanPopulationSystem;
   443→    const populationFraction = pop.population / pop.baselinePopulation;
   444→    
   445→    // Energy infrastructure requires maintenance crews
