   447→      ? 0.3 + (populationFraction * 0.7)
   448→      : 0.65 + (populationFraction * 0.35);
   449→    
   450→    // Renewable/fusion breakthrough assumption at Stage 4
   451→    energyAvailability += 0.6 * gridScaling;
   452→    
   453→    // AI optimization of energy systems (capped to prevent infinite)
   454→    const aiEnergyBonus = Math.min(1.0, totalAICapability * 0.1);
   455→    energyAvailability += aiEnergyBonus * gridScaling;
   456→    
   457→    // Cap at reasonable post-scarcity levels
   458→    energyAvailability = Math.min(3.0, Math.max(0, energyAvailability));
   459→  } else {
   460→    energyAvailability = Math.max(0, Math.min(2, energyAvailability));
   461→  }
   462→  
   463→  // === POPULATION COLLAPSE PENALTY (ENERGY) ===
   464→  // FIX (Oct 13): Energy grids fail without maintenance crews
   465→  if (populationFraction < 0.5) {
