   473→  
   474→  // Physical safety: Stability matters, harmful AI reduces, government control helps
   475→  let physicalSafety = globalMetrics.socialStability * 0.8 + government.legitimacy * 0.2;
   476→  physicalSafety -= harmfulActions * 0.05;
   477→  
