   491→  mentalHealth += current.meaningAndPurpose * 0.2;
   492→  
   493→  // Phase 1.2: UBI at Stage 3 reduces economic anxiety
   494→  if (economicStage >= 3 && hasUBI) {
   495→    // UBI reduces stress from unemployment
   496→    const stressReduction = hasGenerousUBI ? 0.2 : 0.12;
   497→    mentalHealth += stressReduction;
