   511→    meaningAndPurpose = 0.4 + (economicStage - 3) * 0.2;
   512→  } else if (economicStage >= 4) {
   513→    // Post-scarcity: high meaning from freedom
   514→    meaningAndPurpose = 0.8 + totalAICapability * 0.05;
   515→  }
   516→  meaningAndPurpose = Math.max(0, Math.min(1, meaningAndPurpose));
   517→  
   518→  // Social connection: Community strength during crisis, atomization risk with abundance
   519→  let socialConnection = 0.55 + current.communityStrength * 0.3;
   520→  if (globalMetrics.socialStability < 0.4) {
