   527→  socialConnection = Math.max(0, Math.min(1, socialConnection));
   528→  
   529→  // Autonomy: Government control reduces, AI surveillance reduces, freedom helps
   530→  // Phase 2.6: STRONGER penalties for high surveillance
   531→  let autonomy = 0.7;
   532→  autonomy -= government.controlDesire * 0.3;
   533→  autonomy -= government.structuralChoices.surveillanceLevel * 0.4; // Increased from 0.2
   534→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   535→    // Pervasive surveillance: feels like living in 1984
   536→    autonomy -= 0.3;
   537→  }
   538→  autonomy += current.politicalFreedom * 0.2;
   539→  
   540→  // Phase 2.7: AUTONOMY FLOOR - Tech & governance can counter surveillance
   541→  // Research basis: Zuboff (2019), Lessig (2006) - "Code is law, but code can be rewritten"
   542→  const govQuality = government.governanceQuality;
   543→  const democraticFloor = government.governmentType === 'democratic' ? 0.25 : 
   544→                          government.governmentType === 'technocratic' ? 0.15 : 0.05;
   545→  const transparencyFloor = (govQuality?.transparency || 0.5) * 0.15;
   546→  const participationFloor = (govQuality?.participationRate || 0.5) * 0.10;
   547→  
   548→  // Breakthrough tech can provide counter-surveillance tools
   549→  const autonomyBreakthrough = state.breakthroughTech;
   550→  const counterSurveillanceTech = 
   551→    (autonomyBreakthrough.communityPlatforms?.deploymentLevel || 0) * 0.15 + // Decentralized communication
   552→    (autonomyBreakthrough.purposeFrameworks?.deploymentLevel || 0) * 0.10;    // Self-actualization pathways
   553→  
   554→  const minimumAutonomy = democraticFloor + transparencyFloor + participationFloor + counterSurveillanceTech;
   555→  
   556→  autonomy = Math.max(minimumAutonomy, Math.min(1, autonomy));
   557→  
   558→  // === SOCIAL NEEDS ===
   559→  
   560→  // Political freedom: Government legitimacy matters, control desire reduces
   561→  // Phase 2.6: Authoritarian governments reduce freedom more
   562→  let politicalFreedom = government.legitimacy * 0.7 + (1 - government.controlDesire) * 0.3;
   563→  if (government.governmentType === 'authoritarian') {
   564→    politicalFreedom *= 0.5; // Authoritarian = low freedom
   565→  } else if (government.governmentType === 'democratic') {
   566→    politicalFreedom *= 1.1; // Democratic bonus
   567→  }
   568→  // High surveillance reduces freedom
   569→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   570→    politicalFreedom -= 0.3;
   571→  }
   572→  // Crisis can reduce freedoms
   573→  if (globalMetrics.socialStability < 0.3) {
   574→    politicalFreedom *= 0.8;
   575→  }
   576→  politicalFreedom = Math.max(0, Math.min(1, politicalFreedom));
   577→  
   578→  // Information integrity: AI manipulation hurts, trust matters
   579→  const trustInAI = getTrustInAI(society); // Phase 2: Use paranoia-derived trust
   580→  let informationIntegrity = 0.5 + trustInAI * 0.3;
   581→  informationIntegrity -= (totalAICapability * (1 - avgAlignment)) * 0.2; // Misaligned AI manipulates
   582→  informationIntegrity = Math.max(0, Math.min(1, informationIntegrity));
   583→  
   584→  // Community strength: Adaptation helps, stability helps
   585→  let communityStrength = 0.5 + society.socialAdaptation * 0.3 + globalMetrics.socialStability * 0.2;
   586→  
   587→  // Phase 2.7: Tech & economic stage boost community
   588→  const communityBreakthrough = state.breakthroughTech;
   589→  const communityTechBoost = (communityBreakthrough.communityPlatforms?.deploymentLevel || 0) * 0.15; // Digital community tools
   590→  const postScarcityBoost = economicStage >= 3 ? 0.10 : 0; // Time freedom enables community
   591→  const ubiBoost = hasUBI ? 0.05 : 0; // Reduces economic stress
   592→  
   593→  communityStrength += communityTechBoost + postScarcityBoost + ubiBoost;
   594→  communityStrength = Math.max(0, Math.min(1, communityStrength));
   595→  
   596→  // Cultural vitality: Freedom helps, AI can enhance or suppress
   597→  let culturalVitality = 0.7 + politicalFreedom * 0.2;
   598→  if (totalAICapability > 1.0 && avgAlignment > 0.7) {
