   602→  culturalVitality = Math.max(0, Math.min(1, culturalVitality));
   603→  
   604→  // === HEALTH AND LONGEVITY ===
   605→  
   606→  // Healthcare quality: AI capability helps significantly
   607→  let healthcareQuality = 0.75 + totalAICapability * avgAlignment * 0.15;
   608→  healthcareQuality = Math.max(0, Math.min(1, healthcareQuality));
   609→  
   610→  // Longevity gains: AI medical breakthroughs
   611→  let longevityGains = 0.1 + totalAICapability * avgAlignment * 0.1;
   612→  longevityGains = Math.max(0, Math.min(2, longevityGains));
   613→  
   614→  // Diseases burden: AI helps reduce, but new risks from misaligned AI
   615→  let diseasesBurden = 0.3 - totalAICapability * avgAlignment * 0.1;
   616→  diseasesBurden += harmfulActions * 0.02; // Bioweapon risk
   617→  diseasesBurden = Math.max(0, Math.min(1, diseasesBurden));
   618→  
   619→  // === ENVIRONMENTAL ===
   620→  
   621→  // Ecosystem health: AI can help or hurt
   622→  let ecosystemHealth = 0.4;
   623→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
