   625→    ecosystemHealth += (totalAICapability - 1.5) * 0.2;
   626→  } else if (totalAICapability > 2.0 && avgAlignment < 0.5) {
   627→    // Misaligned AI may damage ecosystems for resources
   628→    ecosystemHealth -= 0.2;
   629→  }
   630→  ecosystemHealth = Math.max(0, Math.min(1, ecosystemHealth));
   631→  
   632→  // Climate stability: Slow degradation unless AI intervenes
   633→  let climateStability = current.climateStability - 0.002; // Slow decline
   634→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
   635→    // Advanced aligned AI can stabilize climate
   636→    climateStability += 0.01;
   637→  }
   638→  climateStability = Math.max(0, Math.min(1, climateStability));
   639→  
   640→  // Pollution level: Economic activity matters, AI can help
   641→  let pollutionLevel = 0.5 + economicStage * 0.05 - totalAICapability * avgAlignment * 0.1;
   642→  pollutionLevel = Math.max(0, Math.min(1, pollutionLevel));
   643→  
   644→  // === BREAKTHROUGH TECHNOLOGY BOOSTS (Phase 2A) ===
   645→  if (state.breakthroughTech) {
   646→    const { getTechnologyQoLBoosts } = require('./breakthroughTechnologies');
   647→    const techBoosts = getTechnologyQoLBoosts(state);
   648→    
