   657→    climateStability = Math.min(1.0, climateStability + techBoosts.environmental * 0.5);
   658→  }
   659→  
   660→  // === SURVIVAL FUNDAMENTALS (Oct 12, 2025) ===
   661→  // Calculate core survival metrics separately from aggregate QoL
   662→  const rawFoodSecurity = calculateFoodSecurity(state);
   663→  const rawWaterSecurity = calculateWaterSecurity(state);
   664→  const rawThermalHabitability = calculateThermalHabitability(state);
   665→  const rawShelterSecurity = calculateShelterSecurity(state);
   666→  
   667→  // NaN guards for survival fundamentals
   668→  const survivalFundamentals = {
