   741→/**
   742→ * Calculate regional QoL inequality (Oct 12, 2025)
   743→ * 
   744→ * Global averages hide massive suffering - some regions in famine while others abundant.
   745→ * This tracks the variance in QoL across crisis-affected vs. non-affected regions.
   746→ */
   747→function calculateRegionalInequality(
   748→  state: GameState,
   749→  avgQoL: {
   750→    materialAbundance: number;
   751→    energyAvailability: number;
   752→    physicalSafety: number;
   753→    mentalHealth: number;
   754→    healthcareQuality: number;
   755→  }
   756→): {
   757→  giniCoefficient: number;
   758→  topRegionQoL: number;
   759→  bottomRegionQoL: number;
   760→  qolGap: number;
   761→  crisisAffectedPopulation: number;
   762→} {
   763→  const env = state.environmentalAccumulation;
   764→  const social = state.socialAccumulation;
   765→  const pop = state.humanPopulationSystem;
   766→  const refugees = state.refugeeCrisisSystem;
   767→  
   768→  // Estimate crisis-affected population
   769→  // Based on active crises, refugee counts, and population decline
   770→  let crisisAffectedPopulation = 0;
   771→  
   772→  // Environmental crises affect specific regions
   773→  if (env.resourceCrisisActive) crisisAffectedPopulation += 0.25; // Food/water insecure regions
   774→  if (env.climateCatastropheActive) crisisAffectedPopulation += 0.15; // Coastal & vulnerable
   775→  if (env.ecosystemCollapseActive) crisisAffectedPopulation += 0.10; // Ecosystem-dependent
   776→  
   777→  // Social crises affect specific demographics
   778→  if (social.meaningCollapseActive) crisisAffectedPopulation += 0.30; // Wealthy automated nations
   779→  if (social.socialUnrestActive) crisisAffectedPopulation += 0.20; // Urban centers
   780→  
   781→  // Refugees are definitely crisis-affected
   782→  if (refugees && refugees.activeCrises) {
   783→    const refugeePopulation = Object.values(refugees.activeCrises)
   784→      .reduce((sum, crisis) => sum + crisis.totalFled, 0);
   785→    crisisAffectedPopulation += (refugeePopulation / 1000) / pop.population; // millions to billions
   786→  }
   787→  
   788→  // Cap at 100%
   789→  crisisAffectedPopulation = Math.min(1.0, crisisAffectedPopulation);
   790→  
   791→  // Calculate bottom region QoL (crisis-affected)
   792→  // These regions experience the full brunt of crises
   793→  const crisisMultiplier = 0.3; // 70% reduction in crisis zones
   794→  const bottomRegionQoL = (
   795→    avgQoL.materialAbundance * crisisMultiplier * 0.3 +
   796→    avgQoL.energyAvailability * crisisMultiplier * 0.3 +
   797→    avgQoL.physicalSafety * crisisMultiplier * 0.2 +
   798→    avgQoL.mentalHealth * crisisMultiplier * 0.1 +
   799→    avgQoL.healthcareQuality * crisisMultiplier * 0.1
   800→  );
   801→  
   802→  // Calculate top region QoL (non-affected or benefiting)
   803→  // These regions may even benefit from AI abundance
   804→  const benefitMultiplier = crisisAffectedPopulation > 0.3 ? 1.3 : 1.1;
   805→  const topRegionQoL = (
   806→    avgQoL.materialAbundance * benefitMultiplier * 0.3 +
   807→    avgQoL.energyAvailability * benefitMultiplier * 0.3 +
   808→    avgQoL.physicalSafety * Math.min(1, avgQoL.physicalSafety * 1.2) * 0.2 +
   809→    avgQoL.mentalHealth * Math.min(1, avgQoL.mentalHealth * 1.1) * 0.1 +
   810→    avgQoL.healthcareQuality * Math.min(1, avgQoL.healthcareQuality * 1.2) * 0.1
   811→  );
   812→  
   813→  const qolGap = topRegionQoL - bottomRegionQoL;
   814→  
   815→  // Calculate Gini coefficient (0 = perfect equality, 1 = extreme inequality)
   816→  // Simple approximation: If crisis affects 30% at 0.3x QoL and 70% at 1.3x QoL
   817→  // Gini increases with both the gap and the population affected
   818→  const giniCoefficient = Math.min(1.0, 
   819→    qolGap * 0.5 + // Gap contribution
   820→    crisisAffectedPopulation * 0.3 // Population affected contribution
   821→  );
   822→  
   823→  return {
   824→    giniCoefficient,
   825→    topRegionQoL,
   826→    bottomRegionQoL,
   827→    qolGap,
   828→    crisisAffectedPopulation
   829→  };
   830→}
