   832→/**
   833→ * SURVIVAL FUNDAMENTALS CALCULATIONS (Oct 12, 2025)
   834→ * 
   835→ * These track whether people's basic survival needs are met.
   836→ * Unlike aggregate metrics, these focus on worst-case and cannot be averaged away.
   837→ */
   838→
   839→/**
   840→ * Calculate food security across population
   841→ * 
   842→ * Research basis:
   843→ * - FAO: 1800+ kcal/day minimum for survival
   844→ * - Food security = availability + access + utilization + stability
   845→ * - Phosphorus depletion, ocean collapse, water stress, temperature all affect food
   846→ */
   847→export function calculateFoodSecurity(state: GameState): number {
   848→  const resources = state.resourceEconomy;
   849→  const phosphorus = state.phosphorusDepletion;
   850→  const ocean = state.oceanAcidification;
   851→  const freshwater = state.freshwaterDepletion;
   852→  
   853→  // Base food availability from resource stocks
   854→  let foodSecurity = Math.min(1.0, resources.food.currentStock / 100);
   855→  
   856→  // === PHOSPHORUS DEPLETION ===
   857→  // Low reserves = reduced agricultural yields
   858→  if (phosphorus && phosphorus.reserves < 0.50) {
   859→    const depletionPenalty = (0.50 - phosphorus.reserves) * 0.8;
   860→    foodSecurity -= depletionPenalty;
   861→  }
   862→  
   863→  // High phosphorus prices = food price crisis (access problem)
   864→  // Research: 2007-08 food crisis saw 4x prices, 40M+ pushed into poverty
   865→  if (phosphorus && phosphorus.priceIndex > 2.0) {
   866→    const priceAccessPenalty = Math.min(0.4, (phosphorus.priceIndex - 2.0) * 0.05);
   867→    foodSecurity -= priceAccessPenalty;
   868→  }
   869→  
   870→  // === OCEAN ACIDIFICATION ===
   871→  // Marine food web collapse affects 3 billion fish-dependent people
   872→  // Research: 37.5% of global population relies on fish as primary protein
   873→  if (ocean && ocean.marineFoodWebCollapseActive) {
   874→    const fishDependentPenalty = ocean.fishDependentImpact * 0.375;
   875→    foodSecurity -= fishDependentPenalty;
   876→  }
   877→  
   878→  // === FRESHWATER STRESS ===
   879→  // Agriculture uses 70% of freshwater - stress directly impacts food production
   880→  if (freshwater && freshwater.waterStress > 0.50) {
   881→    const waterPenalty = (freshwater.waterStress - 0.50) * 0.6;
   882→    foodSecurity -= waterPenalty;
   883→  }
   884→  
   885→  // === TEMPERATURE STRESS ===
   886→  // Research: Each 1°C above 1.5°C reduces crop yields 10-15%
   887→  // Major crops (wheat, rice, maize) have temperature optima
   888→  const tempAnomaly = resources.co2.temperatureAnomaly;
   889→  if (tempAnomaly > 1.5) {
   890→    const climatePenalty = (tempAnomaly - 1.5) * 0.15; // 15% per degree
   891→    foodSecurity -= climatePenalty;
   892→  }
   893→  
   894→  // === BIODIVERSITY LOSS ===
   895→  // Research: IPBES (2016), Bardgett & van der Putten (2014), FAO soil reports
   896→  // Biodiversity loss affects food security through multiple pathways:
   897→  // 1. Pollinator decline (35% of crops depend on animal pollinators)
   898→  // 2. Soil health degradation (95% of food comes from soil)
   899→  // 3. Loss of natural pest control
   900→  if (state.biodiversitySystem) {
   901→    const globalBio = state.biodiversitySystem.globalBiodiversityIndex;
   902→    
   903→    // Pollination crisis
   904→    // IPBES: 35% of global food crops depend on pollinators
   905→    // Threshold at 80% biodiversity (pollinators decline faster than general biodiversity)
   906→    if (globalBio < 0.80) {
   907→      const pollinatorLoss = 0.80 - globalBio;
   908→      const pollinationPenalty = pollinatorLoss * 0.35; // Up to 35% loss at bio=45%
   909→      foodSecurity -= pollinationPenalty;
   910→    }
   911→    
   912→    // Soil health degradation
   913→    // Microbiomes, decomposers, nutrient cycling
   914→    // 95% of food comes from soil
   915→    if (globalBio < 0.60) {
   916→      const soilHealthLoss = 0.60 - globalBio;
   917→      const soilPenalty = soilHealthLoss * 0.25; // Up to 25% loss at bio=35%
   918→      foodSecurity -= soilPenalty;
   919→    }
   920→    
   921→    // Natural pest control loss
   922→    // Without predators: 20-30% higher crop losses
   923→    if (globalBio < 0.50) {
   924→      const pestControlLoss = 0.50 - globalBio;
   925→      const pestPenalty = pestControlLoss * 0.20; // Up to 20% loss at bio=30%
   926→      foodSecurity -= pestPenalty;
   927→    }
   928→  }
   929→  
   930→  // === AI ENHANCEMENT ===
   931→  // Aligned superintelligent AI can help food production
   932→  // Precision agriculture, vertical farms, synthetic biology
   933→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   934→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
   935→  if (totalAI > 1.5 && avgAlignment > 0.7) {
   936→    const aiAgriculture = Math.min(0.3, (totalAI - 1.5) * 0.1);
   937→    foodSecurity += aiAgriculture;
   938→  }
   939→  
   940→  // === BREAKTHROUGH TECHNOLOGY ===
   941→  // Sustainable agriculture: closed-loop systems, hydroponics, cellular agriculture
   942→  const sustainableAg = state.breakthroughTech.sustainableAgriculture?.deploymentLevel || 0;
   943→  foodSecurity += sustainableAg * 0.3; // Up to +30% food security
   944→  
   945→  return Math.max(0, Math.min(1.5, foodSecurity));
   946→}
