   952→function getRegionalPopulationProportion(regionName: string): number {
   953→  const proportions: Record<string, number> = {
   954→    'Asia': 0.60,         // 4.7B / 8B
   955→    'Africa': 0.18,       // 1.4B / 8B
   956→    'South America': 0.05, // 0.43B / 8B
   957→    'North America': 0.07, // 0.58B / 8B
