   964→/**
   965→ * Check regional biodiversity for famine risk
   966→ * Triggers famines when regional ecosystems collapse
   967→ * 
   968→ * Research: IPBES (2019), FAO State of Food Security (2024)
   969→ * Ecosystem collapse → agricultural failure → famine
   970→ */
   971→export function checkRegionalFamineRisk(state: GameState, month: number): void {
   972→  if (!state.famineSystem) {
   973→    console.warn(`⚠️  [Month ${month}] checkRegionalFamineRisk: famineSystem is undefined!`);
   974→    return;
   975→  }
   976→  
   977→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, NOT environmentalAccumulation!
   978→  // BUG: Was checking env.foodSecurity (undefined) → always defaulted to 0.7 → never triggered!
   979→  const env = state.environmentalAccumulation;
   980→  const globalFoodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
   981→  
   982→  // FIX (Oct 13, 2025): Simplified famine trigger based on global food security only
   983→  // The regional biodiversity system isn't being maintained, so we can't rely on it
   984→  // Research: FAO, IPBES - food security < 0.4 = famine risk
   985→  
   986→  if (globalFoodSecurity < 0.4) {
   987→    const totalPopulation = state.humanPopulationSystem.population;
   988→    
   989→    // Define 6 major world regions (simplified, not tied to biodiversity system)
   990→    const worldRegions = [
   991→      { name: 'Asia', popFraction: 0.60 },
   992→      { name: 'Africa', popFraction: 0.18 },
   993→      { name: 'Europe', popFraction: 0.09 },
   994→      { name: 'North America', popFraction: 0.07 },
   995→      { name: 'South America', popFraction: 0.05 },
   996→      { name: 'Oceania', popFraction: 0.01 }
   997→    ];
   998→    
   999→    // How many regions to trigger famine in, based on severity
  1000→    // Research: Severe food crisis affects multiple regions simultaneously
  1001→    const regionsToTrigger = globalFoodSecurity < 0.1 ? 6 :  // Global famine
  1002→                             globalFoodSecurity < 0.2 ? 4 :  // Severe crisis (Asia, Africa, ...)
  1003→                             globalFoodSecurity < 0.3 ? 2 :  // Major crisis (Asia, Africa)
  1004→                             1;                              // Regional crisis (Asia)
  1005→    
  1006→    for (let i = 0; i < regionsToTrigger; i++) {
  1007→      const region = worldRegions[i];
  1008→      
  1009→      // Skip if famine already active in this region
  1010→      const existingFamine = state.famineSystem.activeFamines.find(
  1011→        f => f.affectedRegion === region.name
  1012→      );
  1013→      if (existingFamine) continue;
  1014→      
  1015→      // Calculate population at risk
  1016→      // Research: Severe food crisis puts 30-80% of regional population at risk
  1017→      const severityFactor = (0.4 - globalFoodSecurity) / 0.4; // 0-1 scale
  1018→      const atRiskFraction = 0.30 + (severityFactor * 0.50); // 30-80% at risk
  1019→      const populationAtRisk = totalPopulation * region.popFraction * atRiskFraction;
  1020→      
  1021→      // Determine cause
  1022→      let cause: import('../types/famine').FamineCause = 'crop_failure';
  1023→      if (state.phosphorusDepletion?.globalSupplyShock > 3.0) {
  1024→        cause = 'supply_chain_collapse';
  1025→      } else if (env.climateStability < 0.4) {
  1026→        cause = 'drought';
  1027→      }
  1028→      
  1029→      // Trigger famine with realistic death curve (2% → 8% → 15% → 10% → 2% over months)
  1030→      const { triggerFamine } = require('../types/famine');
  1031→      triggerFamine(
  1032→        state.famineSystem,
  1033→        month,
  1034→        region.name,
  1035→        populationAtRisk,
  1036→        cause,
  1037→        globalFoodSecurity
  1038→      );
  1039→      
  1040→      console.log(`\n🌾💀 GLOBAL FOOD CRISIS FAMINE: ${region.name}`);
  1041→      console.log(`   Global food security: ${(globalFoodSecurity * 100).toFixed(1)}%`);
  1042→      console.log(`   Population at risk: ${(populationAtRisk * 1000).toFixed(0)}M (${(atRiskFraction * 100).toFixed(0)}% of region)`);
  1043→      console.log(`   Cause: ${cause}`);
  1044→      console.log(`   Expected deaths: ~${(populationAtRisk * 0.37 * 1000).toFixed(0)}M over 6 months if no intervention\n`);
  1045→    }
  1046→  }
  1047→}
