  1049→/**
  1050→ * Calculate water security across population
  1051→ * 
  1052→ * Research basis:
  1053→ * - WHO: 50L/day minimum for health (drinking, cooking, hygiene)
  1054→ * - 20L/day survival minimum
  1055→ * - Freshwater depletion, climate change, pollution all threaten water access
  1056→ */
  1057→export function calculateWaterSecurity(state: GameState): number {
  1058→  const resources = state.resourceEconomy;
  1059→  const freshwater = state.freshwaterDepletion;
  1060→  const ocean = state.oceanAcidification;
  1061→  
  1062→  // Base water availability from resource stocks
  1063→  let waterSecurity = Math.min(1.0, resources.water.reserves);
  1064→  
  1065→  // === FRESHWATER DEPLETION ===
  1066→  // Day Zero droughts = acute water crisis
  1067→  if (freshwater && freshwater.dayZeroDrought.active) {
  1068→    const droughtSeverity = freshwater.dayZeroDrought.severity;
  1069→    waterSecurity -= droughtSeverity * 0.4; // Up to 40% reduction
  1070→  }
  1071→  
  1072→  // Peak Groundwater = declining availability
  1073→  if (freshwater && freshwater.peakGroundwater.active) {
  1074→    const depletionRate = freshwater.peakGroundwater.depletionRate;
  1075→    waterSecurity -= depletionRate * 0.3;
  1076→  }
  1077→  
  1078→  // General water stress
  1079→  if (freshwater && freshwater.waterStress > 0.40) {
  1080→    const stressPenalty = (freshwater.waterStress - 0.40) * 0.5;
  1081→    waterSecurity -= stressPenalty;
  1082→  }
  1083→  
  1084→  // === CLIMATE IMPACT ===
  1085→  // Temperature anomalies disrupt water cycle
  1086→  // Research: Each 1°C = 7% more atmospheric water vapor = more droughts AND floods
  1087→  const tempAnomaly = resources.co2.temperatureAnomaly;
  1088→  if (tempAnomaly > 2.0) {
  1089→    const climatePenalty = (tempAnomaly - 2.0) * 0.1;
  1090→    waterSecurity -= climatePenalty;
  1091→  }
  1092→  
  1093→  // === POLLUTION ===
  1094→  // Novel entities (PFAS, microplastics) contaminate water supplies
  1095→  if (state.novelEntities && state.novelEntities.pfasConcentration > 70) {
  1096→    const contamination = (state.novelEntities.pfasConcentration - 70) / 30; // 70-100 scale
  1097→    waterSecurity -= contamination * 0.15; // Up to 15% reduction
  1098→  }
  1099→  
  1100→  // === AI ENHANCEMENT ===
  1101→  // Desalination, water purification, infrastructure optimization
  1102→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1103→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1104→  if (totalAI > 1.5 && avgAlignment > 0.7) {
  1105→    const aiWater = Math.min(0.25, (totalAI - 1.5) * 0.08);
  1106→    waterSecurity += aiWater;
  1107→  }
  1108→  
  1109→  // === BREAKTHROUGH TECHNOLOGY ===
  1110→  // Clean energy enables desalination at scale
  1111→  const cleanEnergy = state.breakthroughTech.cleanEnergy?.deploymentLevel || 0;
  1112→  waterSecurity += cleanEnergy * 0.15; // Desalination powered by clean energy
  1113→  
  1114→  return Math.max(0, Math.min(1.5, waterSecurity));
  1115→}
