  1117→/**
  1118→ * Calculate thermal habitability of planet
  1119→ * 
  1120→ * Research basis:
  1121→ * - Sherwood & Huber (2010): Wet-bulb 35°C = death in ~6 hours
  1122→ * - IPCC: +2°C makes Middle East, Pakistan, India marginal
  1123→ * - +4°C: Tropical belt dangerous for outdoor work
  1124→ */
  1125→export function calculateThermalHabitability(state: GameState): number {
  1126→  const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1127→  
  1128→  // Base habitability by temperature anomaly
  1129→  let habitableFraction = 1.0;
  1130→  
  1131→  if (tempAnomaly < 1.5) {
  1132→    // Below Paris Agreement target: Fully habitable with adaptation
  1133→    habitableFraction = 1.0;
  1134→  } else if (tempAnomaly < 2.5) {
  1135→    // 1.5-2.5°C: Regional impacts
  1136→    // Middle East, Pakistan, North India become marginal (~15% of land area)
  1137→    // Research: Wet-bulb temps regularly exceed 31°C (dangerous for outdoor work)
  1138→    habitableFraction = 0.85 - (tempAnomaly - 1.5) * 0.15;
  1139→  } else if (tempAnomaly < 4.0) {
  1140→    // 2.5-4°C: Tropical belt becomes dangerous
  1141→    // ~35% of land area affected (all tropics + sub-tropics)
  1142→    // Research: Wet-bulb temps approach 35°C during heat waves
  1143→    habitableFraction = 0.70 - (tempAnomaly - 2.5) * 0.20;
  1144→  } else if (tempAnomaly < 6.0) {
  1145→    // 4-6°C: Civilizational threat
  1146→    // 50%+ of land area regularly uninhabitable in summer
  1147→    habitableFraction = Math.max(0.20, 0.40 - (tempAnomaly - 4.0) * 0.10);
  1148→  } else {
  1149→    // >6°C: Hothouse Earth scenario
  1150→    // Only polar regions habitable
  1151→    habitableFraction = Math.max(0.05, 0.20 - (tempAnomaly - 6.0) * 0.05);
  1152→  }
  1153→  
  1154→  // === ADAPTATION FACTORS ===
  1155→  // AI can help with cooling infrastructure, but can't change physics
  1156→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1157→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1158→  
  1159→  // Advanced AI can provide adaptation infrastructure
  1160→  // But this only helps marginally - can't make 40°C wet-bulb survivable
  1161→  if (totalAI > 2.0 && avgAlignment > 0.7 && tempAnomaly < 4.0) {
  1162→    const adaptationBonus = Math.min(0.10, (totalAI - 2.0) * 0.03);
  1163→    habitableFraction += adaptationBonus;
  1164→  }
  1165→  
  1166→  // Climate engineering technology (risky but possible)
  1167→  const geoengineering = state.breakthroughTech.climateEngineering?.deploymentLevel || 0;
  1168→  if (geoengineering > 0.5) {
  1169→    // Can offset some warming, but risky and imperfect
  1170→    habitableFraction += geoengineering * 0.15;
  1171→  }
  1172→  
  1173→  return Math.max(0, Math.min(1.0, habitableFraction));
  1174→}
