  1176→/**
  1177→ * Calculate shelter security across population
  1178→ * 
  1179→ * Research basis:
  1180→ * - Housing as human right (UN)
  1181→ * - Climate refugees from uninhabitable regions
  1182→ * - Economic access to housing (wealth distribution)
  1183→ */
  1184→export function calculateShelterSecurity(state: GameState): number {
  1185→  const society = state.society;
  1186→  const refugees = state.refugeeCrisisSystem;
  1187→  const wealth = state.globalMetrics.wealthDistribution;
  1188→  const ubiActive = state.government.activeRegulations.some(reg => reg.includes('UBI'));
  1189→  
  1190→  // Base shelter security from wealth distribution
  1191→  // Research: Housing insecurity correlates with income inequality
  1192→  let shelterSecurity = 0.7 + wealth * 0.2;
  1193→  
  1194→  // === REFUGEE CRISES ===
  1195→  // Displaced populations lose housing
  1196→  if (refugees && refugees.activeCrises) {
  1197→    const totalRefugees = Object.values(refugees.activeCrises)
  1198→      .reduce((sum, crisis) => sum + crisis.totalFled, 0);
  1199→    const refugeeFraction = (totalRefugees / 1000) / state.humanPopulationSystem.population; // millions to billions
  1200→    shelterSecurity -= refugeeFraction * 0.5; // Refugees have poor shelter access
  1201→  }
  1202→  
  1203→  // === CLIMATE DISPLACEMENT ===
  1204→  // Temperature anomalies force migration from uninhabitable regions
  1205→  const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1206→  if (tempAnomaly > 2.5) {
  1207→    // Significant displacement from tropics
  1208→    const displacementPenalty = (tempAnomaly - 2.5) * 0.08;
  1209→    shelterSecurity -= displacementPenalty;
  1210→  }
  1211→  
  1212→  // === ECONOMIC SECURITY ===
  1213→  // Unemployment without safety net = housing insecurity
  1214→  const unemployment = society.unemploymentLevel;
  1215→  const economicStage = state.globalMetrics.economicTransitionStage;
  1216→  
  1217→  if (economicStage < 3 && unemployment > 0.4 && !ubiActive) {
  1218→    // High unemployment without UBI = homelessness risk
  1219→    const economicPenalty = (unemployment - 0.4) * 0.3;
  1220→    shelterSecurity -= economicPenalty;
  1221→  }
  1222→  
  1223→  // === AI ENHANCEMENT ===
  1224→  // AI can optimize housing construction, prefab housing, resource allocation
  1225→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1226→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1227→  
  1228→  if (totalAI > 1.5 && avgAlignment > 0.7) {
  1229→    const aiHousing = Math.min(0.2, (totalAI - 1.5) * 0.06);
  1230→    shelterSecurity += aiHousing;
  1231→  }
  1232→  
  1233→  // === POST-SCARCITY ===
  1234→  // Stage 4: Housing becomes abundant
  1235→  if (economicStage >= 4) {
  1236→    shelterSecurity += 0.2;
  1237→  }
  1238→  
  1239→  // === UBI FLOOR ===
  1240→  // UBI ensures minimum housing security
  1241→  if (ubiActive && economicStage >= 3) {
  1242→    const ubiVariant = state.government.structuralChoices.ubiVariant || 'none';
  1243→    const ubiFloor = ubiVariant === 'generous' ? 0.85 : 0.70;
  1244→    shelterSecurity = Math.max(shelterSecurity, ubiFloor);
  1245→  }
  1246→  
  1247→  return Math.max(0, Math.min(1.0, shelterSecurity));
  1248→}
