  1250→/**
  1251→ * ENHANCED DISTRIBUTION METRICS (Oct 12, 2025)
  1252→ * 
  1253→ * Calculate QoL inequality across regions to detect dystopian scenarios where
  1254→ * aggregate metrics look fine but specific populations suffer.
  1255→ * 
  1256→ * Research basis:
  1257→ * - Wilkinson & Pickett (2009): Gini >0.45 = social instability
  1258→ * - Rawls: Justice requires maximizing the welfare of the worst-off
  1259→ * - "Two worlds" dystopia: Some thrive while others suffer
  1260→ */
  1261→export function calculateDistributionMetrics(
  1262→  state: GameState,
  1263→  survivalFundamentals: {
  1264→    foodSecurity: number;
  1265→    waterSecurity: number;
  1266→    thermalHabitability: number;
  1267→    shelterSecurity: number;
  1268→  },
  1269→  basicQoL: {
  1270→    materialAbundance: number;
  1271→    energyAvailability: number;
  1272→    physicalSafety: number;
  1273→    mentalHealth: number;
  1274→    healthcareQuality: number;
  1275→  }
  1276→): {
  1277→  globalGini: number;
  1278→  regionalVariance: number;
  1279→  crisisAffectedFraction: number;
  1280→  worstRegionQoL: number;
  1281→  bestRegionQoL: number;
  1282→  medianRegionQoL: number;
  1283→  isDystopicInequality: boolean;
  1284→  isRegionalDystopia: boolean;
  1285→} {
  1286→  const regions = state.regionalPopulations;
  1287→  const env = state.environmentalAccumulation;
  1288→  const social = state.socialAccumulation;
  1289→  const refugees = state.refugeeCrisisSystem;
  1290→  const pop = state.humanPopulationSystem;
  1291→  
  1292→  // Calculate QoL for each region
  1293→  const regionalQoLs: number[] = [];
  1294→  let totalCrisisAffected = 0;
  1295→  
  1296→  if (regions && regions.regions) {
  1297→    for (const region of regions.regions) {
  1298→      // Region-specific modifiers based on crisis exposure
  1299→      let regionQoL = 0;
  1300→      
  1301→      // === SURVIVAL FUNDAMENTALS (weighted heavily) ===
  1302→      // These are most affected by regional crises
  1303→      let regionFoodSecurity = survivalFundamentals.foodSecurity;
  1304→      let regionWaterSecurity = survivalFundamentals.waterSecurity;
  1305→      let regionShelter = survivalFundamentals.shelterSecurity;
  1306→      
  1307→      // Water stress affects specific regions more
  1308→      if (region.freshwaterStress > 0.7) {
  1309→        regionWaterSecurity *= (1 - region.freshwaterStress * 0.5);
  1310→        regionFoodSecurity *= (1 - region.freshwaterStress * 0.3); // Agriculture needs water
  1311→      }
  1312→      
  1313→      // Drought-affected regions
  1314→      if (region.droughtAffected) {
  1315→        regionWaterSecurity *= 0.4; // 60% reduction in drought zones
  1316→        regionFoodSecurity *= 0.5; // 50% reduction
  1317→      }
  1318→      
  1319→      // Resource vulnerability (food import dependency)
  1320→      if (region.resourceVulnerability > 0.7) {
  1321→        regionFoodSecurity *= (1 - region.resourceVulnerability * 0.4);
  1322→      }
  1323→      
  1324→      // Refugee hosting strains infrastructure
  1325→      if (region.refugeesHosted > 0) {
  1326→        const refugeeStrain = Math.min(0.4, region.refugeesHosted / region.population);
  1327→        regionShelter -= refugeeStrain;
  1328→      }
  1329→      
  1330→      // Thermal habitability varies by latitude
  1331→      // Tropical regions hit harder by temperature rise
  1332→      const isTropical = region.name.includes('Africa') || 
  1333→                         region.name.includes('South Asia') || 
  1334→                         region.name.includes('Southeast Asia') ||
  1335→                         region.name.includes('Middle East');
  1336→      let regionHabitability = survivalFundamentals.thermalHabitability;
  1337→      if (isTropical) {
  1338→        const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1339→        if (tempAnomaly > 1.5) {
  1340→          // Tropical regions become uninhabitable faster
  1341→          regionHabitability *= Math.max(0.3, 1 - (tempAnomaly - 1.5) * 0.25);
  1342→        }
  1343→      }
  1344→      
  1345→      // Survival fundamentals contribution (40% weight)
  1346→      const survivalScore = (
  1347→        regionFoodSecurity * 0.30 +
  1348→        regionWaterSecurity * 0.30 +
  1349→        regionHabitability * 0.25 +
  1350→        regionShelter * 0.15
  1351→      );
  1352→      
  1353→      // === BASIC NEEDS (30% weight) ===
  1354→      // Modified by economic access and infrastructure
  1355→      let regionMaterial = basicQoL.materialAbundance;
  1356→      let regionEnergy = basicQoL.energyAvailability;
