   209→export class SeededRandom {
   210→  private seed: number;
   211→  
   212→  constructor(seed: number) {
   213→    this.seed = seed;
   214→  }
   215→  
   216→  /**
   217→   * Generate next random number [0, 1)
   218→   */
   219→  next(): number {
   220→    // Simple LCG (Linear Congruential Generator)
   221→    this.seed = (this.seed * 1664525 + 1013904223) % 2**32;
   222→    return this.seed / 2**32;
   223→  }
   224→  
   225→  /**
   226→   * Generate random number in range [min, max)
   227→   */
   228→  range(min: number, max: number): number {
   229→    return min + this.next() * (max - min);
   230→  }
   231→  
   232→  /**
   233→   * Generate random boolean with given probability
   234→   */
   235→  chance(probability: number): boolean {
   236→    return this.next() < probability;
   237→  }
   238→  
   239→  /**
   240→   * Choose random element from array
   241→   */
   242→  choose<T>(array: T[]): T {
   243→    return array[Math.floor(this.next() * array.length)];
   244→  }
   245→}
