   292→    economicStageReached: number;
   293→  };
   294→}
   295→
   296→/**
   297→ * Core simulation engine
   298→ * 
   299→ * This engine is pure and deterministic - given the same initial state and seed,
   300→ * it will always produce the same results. This is critical for:
   301→ * - Reproducible testing
   302→ * - Monte Carlo simulations
   303→ * - Parameter sweeps
   304→ */
   305→export class SimulationEngine {
   306→  private rng: SeededRandom;
   307→  private config: SimulationConfig;
   308→  private orchestrator: PhaseOrchestrator;
   309→
   310→  constructor(config: SimulationConfig = {}) {
   311→    this.config = {
   312→      seed: config.seed ?? Date.now(),
   313→      maxMonths: config.maxMonths ?? 1000,
   314→      governmentActionFrequency: config.governmentActionFrequency ?? 0.5, // Default: 1 action per 2 months
   315→      socialAdaptationRate: config.socialAdaptationRate ?? 1.0,
   316→      aiCoordinationMultiplier: config.aiCoordinationMultiplier ?? 1.0,
   317→      economicTransitionRate: config.economicTransitionRate ?? 1.0,
   318→      snapshotInterval: config.snapshotInterval ?? 12  // Default to quarterly snapshots
   319→    };
   320→
   321→    this.rng = new SeededRandom(this.config.seed!);
   322→
   323→    // Initialize Phase Orchestrator (Phase 4: Engine Orchestration)
   324→    this.orchestrator = new PhaseOrchestrator();
   325→
   326→    // Register all phase implementations
   327→    // Batch 1: Simple calculations (30.x)
   328→    this.orchestrator.registerPhase(new UnemploymentPhase());
   329→    this.orchestrator.registerPhase(new EconomicTransitionPhase());
   330→    this.orchestrator.registerPhase(new ParanoiaPhase());
   331→    this.orchestrator.registerPhase(new SocialStabilityPhase());
   332→    this.orchestrator.registerPhase(new QualityOfLifePhase());
   333→    this.orchestrator.registerPhase(new OutcomeProbabilitiesPhase());
   334→    this.orchestrator.registerPhase(new UpdateEconomicStagePhase());  // P2.4 Feature 3: Recovery tracking
   335→    this.orchestrator.registerPhase(new CrisisDetectionPhase());
   336→
   337→    // Batch 2: System updates (10.x - 21.x)
