   448→  /**
   449→   * Create a deep snapshot of game state, preserving Map and Set objects
   450→   * Uses structuredClone (modern API) which handles complex objects correctly
   451→   */
   452→  private snapshotState(state: GameState): GameState {
   453→    try {
   454→      // structuredClone is available in Node 17+ and modern browsers
   455→      // It correctly handles Map, Set, Date, RegExp, etc.
   456→      return structuredClone(state);
   457→    } catch (error) {
   458→      // Fallback for older Node versions: manual reconstruction
   459→      console.warn('structuredClone not available, using manual snapshot');
   460→
   461→      // Create shallow copy
   462→      const snapshot = { ...state };
   463→
   464→      // Deep clone arrays
   465→      snapshot.aiAgents = state.aiAgents.map(ai => ({ ...ai }));
   466→      snapshot.organizations = state.organizations.map(org => ({ ...org }));
   467→      snapshot.eventLog = [...state.eventLog];
   468→
   469→      // Preserve Map objects
   470→      if (state.computeInfrastructure?.computeAllocations) {
   471→        snapshot.computeInfrastructure = {
   472→          ...state.computeInfrastructure,
   473→          computeAllocations: new Map(state.computeInfrastructure.computeAllocations)
   474→        };
   475→      }
   476→
   477→      // Preserve Set objects
   478→      if (state.radiationSystem?.contaminatedRegions) {
   479→        snapshot.radiationSystem = {
   480→          ...state.radiationSystem,
   481→          contaminatedRegions: new Set(state.radiationSystem.contaminatedRegions)
   482→        };
   483→      }
   484→
   485→      if (state.biodiversitySystem?.regions) {
   486→        snapshot.biodiversitySystem = {
   487→          ...state.biodiversitySystem,
   488→          regions: new Map(state.biodiversitySystem.regions),
   489→          regionalWeights: new Map(state.biodiversitySystem.regionalWeights)
   490→        };
   491→      }
   492→
   493→      return snapshot;
   494→    }
   495→  }
