    [ShockType.NUCLEAR_WAR, ShockType.AGI_BREAKTHROUGH, ShockType.ASTEROID_IMPACT, ShockType.MEGA_PANDEMIC].includes(shockType)
      ? 'civilization-altering'
      : 'major-recoverable';

