     1→/**
     2→ * Exogenous Shock Phase - Phase 2 of Contingency & Agency Modeling
     3→ *
     4→ * Implements rare unpredictable events outside the normal state space evolution.
     5→ *
     6→ * Research Foundation:
     7→ * - Taleb (2007): Black Swan theory - high impact, low predictability events
     8→ * - Sornette (2003): Critical phase transitions in social sciences
     9→ * - IPCC AR6 (2021-2023): Volcanic eruption & shock event modeling methodology
    10→ *
    11→ * Historical Calibration:
    12→ * - 15 black/gray swans in 80 years (1945-2025) = 0.19/year
    13→ * - Stratified by impact severity:
    14→ *   - Black swans (civilization-altering): 0.1% per month (~1% per year)
    15→ *   - Gray swans (major but recoverable): 1% per month (~10% per year)
    16→ *
    17→ * Order: 27.5 (after crisis detection at 36.0, before outcomes)
    18→ */
    19→
    20→import { SimulationPhase, PhaseResult, RNGFunction, PhaseContext } from '../PhaseOrchestrator';
    21→import { GameState, GameEvent } from '@/types/game';
    22→
    23→/**
    24→ * Exogenous Shock Types
    25→ *
    26→ * Stratified by impact severity and recovery potential.
    27→ */
    28→export enum ShockType {
    29→  // BLACK SWAN (0.1% per month) - Civilization-altering
    30→  NUCLEAR_WAR = 'nuclear_war',
    31→  AGI_BREAKTHROUGH = 'agi_breakthrough',
    32→  ASTEROID_IMPACT = 'asteroid_impact',
    33→  MEGA_PANDEMIC = 'mega_pandemic',
    34→
    35→  // GRAY SWAN (1% per month) - Major but recoverable
