    83→ * - Svolik (2012): Democratic breakdowns need both elite defection AND mass mobilization
    84→ * - Kuran (1991): Hidden opposition can suddenly cascade when one person defects
    85→ */
    86→export function isAtCriticalJuncture(state: GameState): boolean {
