    88→  // institutionStrength from governance quality (1.0 = strong, 0.0 = collapsed)
    89→  const institutionStrength = state.government.governanceQuality?.institutionalCapacity || 0.5;
    90→  const institutionalFlux = 1 - institutionStrength;
