    92→  // Threshold: >0.6 means institutions very weak but not destroyed
    93→  // (Too strong = no flux, too weak = no capacity for change)
    94→  const hasInstitutionalFlux = institutionalFlux > 0.6 && institutionStrength > 0.2;
