    96→  // 2. Information Ambiguity (coordination problems)
    97→  // informationIntegrity from information warfare system (1.0 = truth, 0.0 = noise)
    98→  const infoIntegrity = state.globalMetrics.informationIntegrity;
    99→
   100→  // Threshold: <0.5 means high ambiguity (people can't coordinate, hidden preferences)
   101→  const hasInformationAmbiguity = infoIntegrity < 0.5;
   102→
   103→  // 3. Balanced Forces (crisis but recoverable)
