   117→/**
   118→ * Calculate agency potential - probability that escape attempt succeeds
   119→ *
   120→ * Agency potential is HIGHER in:
   121→ * - Democratic systems (Sen 1999: agency as capability)
   122→ * - With latent opposition (Kuran 1991: preference falsification)
   123→ * - With personal authority (Arkhipov case: single vote can matter)
   124→ * - With coordination cascades (Leipzig 1989: one defection triggers cascade)
   125→ * - With organized social movements (collective action)
   126→ *
   127→ * Returns: [0, 1] probability of successful escape
   128→ */
   129→export function calculateAgencyPotential(state: GameState, rng: () => number): number {
   130→  // Not at critical juncture? No agency potential
   131→  if (!isAtCriticalJuncture(state)) {
   132→    return 0;
   133→  }
   134→
   135→  // Base agency from democratic institutions (Sen 1999)
   136→  const democracyIndex = state.governance?.democracyIndex || 0.5;
   137→  const infoIntegrity = state.globalMetrics.informationIntegrity;
