   153→      : 0;
   154→
   155→  // Personal authority (Arkhipov case: 5% probability)
   156→  // Single individual in right place at right time
   157→  const personalAuthority = rng() < 0.05 ? 0.3 : 0;
   158→
   159→  // Social movement strength (organized opposition)
   160→  const movementStrength = state.society.socialMovements?.strength || 0;
   161→
   162→  // Total agency potential (capped at 1.0)
   163→  const agencyPotential = Math.min(
