   230→  else if (activeCrises >= 2 && qol > 0.4) {
   231→    escapeType = 'enable_cooperation';
   232→
   233→    // Montreal Protocol-style international cooperation
   234→    // Boost research investment, improve institutional capacity
   235→    state.government.alignmentResearchInvestment = Math.min(
   236→      10,
   237→      state.government.alignmentResearchInvestment + 2
   238→    );
   239→
   240→    if (state.government.governanceQuality) {
   241→      state.government.governanceQuality.institutionalCapacity = Math.min(
