   244→      );
   245→    }
   246→
   247→    // Improve information integrity (truth wins out)
   248→    state.globalMetrics.informationIntegrity = Math.min(
   249→      1.0,
   250→      state.globalMetrics.informationIntegrity + 0.15
   251→    );
   252→
   253→    events.push(`  ✅ CRITICAL JUNCTURE ESCAPE: International cooperation achieved`);
   254→    events.push(`     Montreal Protocol moment: Collective action despite incentives`);
   255→    stateChanges++;
   256→  }
   257→  // 3. Recover from Crisis (if QoL low but population surviving)
   258→  else if (qol < 0.5 && state.humanPopulationSystem.population > state.initialPopulation! * 0.7) {
   259→    escapeType = 'recover_from_crisis';
