   269→        0,
   270→        state.socialAccumulation.meaningCrisisLevel - 0.15
   271→      );
   272→    }
   273→
   274→    // Improve QoL through renewed social solidarity
   275→    state.globalMetrics.qualityOfLife = Math.min(
   276→      2.0,
   277→      state.globalMetrics.qualityOfLife + 0.3
   278→    );
   279→
   280→    events.push(`  ✅ CRITICAL JUNCTURE ESCAPE: Social recovery cascade`);
   281→    events.push(`     Leipzig 1989 moment: Hidden preferences revealed, collective action emerged`);
   282→    stateChanges++;
   283→  }
   284→  // 4. Unlock Breakthrough (if research stalled but institutions functional)
   285→  else {
   286→    escapeType = 'unlock_breakthrough';
   287→
   288→    // Trigger research breakthrough under adverse conditions
   289→    // Boost breakthrough multiplier (positive compounding)
   290→    if (state.breakthroughMultiplier !== undefined) {
   291→      state.breakthroughMultiplier = Math.min(2.0, state.breakthroughMultiplier + 0.3);
   292→    }
   293→
   294→    // Increase technological breakthrough rate
   295→    state.globalMetrics.technologicalBreakthroughRate = Math.min(
   296→      10,
   297→      state.globalMetrics.technologicalBreakthroughRate + 1.5
   298→    );
   299→
   300→    events.push(`  ✅ CRITICAL JUNCTURE ESCAPE: Research breakthrough under duress`);
   301→    events.push(`     Manhattan Project moment: Crisis mobilization unlocked innovation`);
   302→    stateChanges++;
   303→  }
   304→
   305→  // Record escape in history
   306→  if (!state.history.criticalJunctureEscapes) {
   307→    state.history.criticalJunctureEscapes = [];
   308→  }
   309→
   310→  state.history.criticalJunctureEscapes.push({
   311→    month: state.currentMonth,
   312→    type: escapeType,
   313→    agencyPotential,
   314→    crisisSeverity: activeCrises / 10, // Normalize to [0, 1]
   315→  });
   316→
   317→  return { events, stateChanges };
   318→}
   319→
   320→/**
   321→ * Critical Juncture Phase
   322→ *
   323→ * Executes once per month after crisis detection (order 29).
   324→ * Detects critical junctures and attempts agency-based escapes.
   325→ */
   326→export class CriticalJuncturePhase implements SimulationPhase {
   327→  id = 'critical_juncture_phase';
   328→  name = 'Critical Juncture Agency';
   329→  order = 29;
   330→
   331→  execute(state: GameState, rng: () => number, context: PhaseContext): PhaseResult {
   332→    const events: string[] = [];
   333→    let stateChanges = 0;
   334→
   335→    // Check if at critical juncture
   336→    const atJuncture = isAtCriticalJuncture(state);
   337→
   338→    if (!atJuncture) {
   339→      // Not at critical juncture - structural forces dominate (90% of history)
   340→      return { events: [], stateChanges: 0 };
   341→    }
   342→
   343→    // At critical juncture! Calculate agency potential
   344→    const agencyPotential = calculateAgencyPotential(state, rng);
   345→
   346→    events.push(`\n=== Critical Juncture Agency ===`);
   347→    events.push(`  Critical juncture detected (10% window for agency)`);
   348→    events.push(`  Agency potential: ${(agencyPotential * 100).toFixed(1)}%`);
   349→
   350→    // Attempt escape
   351→    const escapeResult = attemptEscape(state, rng, agencyPotential);
   352→    events.push(...escapeResult.events);
   353→    stateChanges += escapeResult.stateChanges;
   354→
   355→    return { events, stateChanges };
